input.sparql:
SELECT ?people_count_series WHERE {
  ?zone a brick:Building_Floor;
    rdfs:label "Basement";
    brick-controls ?sensor.
  ?sensor a brick:Occupancy_Count_Sensor;
    ref:hasExternalReference/ref:hasTimeseriesId ?people_count_series.
}

SELECT ?people_count_series WHERE {
  ?zone a brick:Zone;
    rdfs:label "Basement";
    brick:hasPoint ?sensor.
  ?sensor a brick:Occupancy_Count_Sensor;
    ref:hasExternalReference/ref:hasTimeseriesId ?people_count_series.
}
